import type { Metadata } from 'next';

export const SITE_URL = 'https://www.caterpillar-consulting.ai';
export const SITE_NAME = 'Caterpillar AI Consulting';

// Title, description, canonical URL and share-preview tags for one page.
// The share image is generated by src/app/opengraph-image.tsx.
const SHARE_IMAGE = { url: '/opengraph-image', width: 1200, height: 630, alt: 'Caterpillar AI Consulting: AI systems and training for small businesses' };
export function pageMeta(path: string, title: string, description: string): Metadata {
  return {
    title,
    description,
    alternates: { canonical: path },
    openGraph: { title, description, url: path, siteName: SITE_NAME, type: 'website', locale: 'en_US', images: [SHARE_IMAGE] },
    twitter: { card: 'summary_large_image', title, description, images: [SHARE_IMAGE.url] },
  };
}
